// Storage utility for session management only
// All data persistence now handled by backend API

export const getSession = () => {
  try {
    return JSON.parse(localStorage.getItem('unihelp_session'));
  } catch {
    return null;
  }
};

export const setSession = (user) => {
  localStorage.setItem('unihelp_session', JSON.stringify(user));
};

export const clearSession = () => {
  localStorage.removeItem('unihelp_session');
};
